import{_ as t,c as s,o as i,j as e,a as n}from"./chunks/framework.Dnh4IO1K.js";const m=JSON.parse('{"title":"周易经传集解卷二十八","description":"周易经传集解 - 周易经传集解卷二十八","frontmatter":{"title":"周易经传集解卷二十八","description":"周易经传集解 - 周易经传集解卷二十八"},"headers":[],"relativePath":"zh/classics/jingchuan-jijie/029.md","filePath":"zh/classics/jingchuan-jijie/029.md"}'),r={name:"zh/classics/jingchuan-jijie/029.md"};function c(o,a,l,d,p,h){return i(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"周易经传集解卷二十八",tabindex:"-1"},[n("周易经传集解卷二十八 "),e("a",{class:"header-anchor",href:"#周易经传集解卷二十八","aria-label":"Permalink to “周易经传集解卷二十八”"},"​")],-1),e("p",null,"钦定四车全书周易经传集解卷二十八 ​宋林栗撰序卦曰：得其所归者必大，故受之以丰。丰者，大也。「丰」，「归妹」之变也。「归妹」之丰，上震不动，下兑为离，二三相易而成卦也。兑，少女；离，中女。少女而归长男，所以为归妹也。兑之从震，必征乎离。万物相见之时，取诸丰盛，不亦宜乎？丰：亨，王假之。勿忧，宜日中。彖曰：丰，大也。明以动，故「丰」。「王假之」，尚大也。「勿忧，宜日中」，宜照天下也。日中则昃，月盈则食，天地盈虚，与时消息，而况于人乎？况于鬼神乎？下离上震，成卦曰「丰」者，初为离，二为巽，三为兑，四为震。离，明也；震，动也。明以动谓之「丰」，何也？为其有巽、兑之象焉。巽，入也；兑，说也。一阳在上，三阴承之，春气发而百草生，正得秋而万宝成，是以谓之「丰」也。离，中女也；震，长男也。中女长男谓之「丰」，何也？为其有巽、兑之象焉。巽，长女也；兑，少女也。一男当室，三女从之。天子有九御，诸侯有三归，是以谓之「丰」也。昔周共王游于㴛上，密康公从，有三女奔之。其母曰：必致之王。人三为众，女三为粲。夫粲，美之志也。众以美物归女，而何德以堪之？故子曰：「丰，大也。明以动，故丰。」愚谓：下「丰」字当作「亨」字，丰亨之义也。按尔雅：苞、芜、茂，丰也。丰文生于手，说文曰：「草盛丰丰也。」丰之二五，皆体乎巽，巽为蕃鲜，故有蕃盛之义，亦有蔽障之义焉。杂卦曰：「丰，多故也。」当丰之时，业巨事丛，朝廷尊安。尊则易骄，安则易惰。骄则日入于壅蔽之域，情则日沦于委靡之涂。惟明，故壅蔽之患不生；惟动，故委靡之渐不作。汉之元帝、唐之文宗，不足于明故也；汉之成帝、唐之穆宗，不足于动故也。天下久安，内外旡患，因循苟且，必有偏而不起之处。惟明以动，故能举偏而补弊，通变而不穷，此其所以亨与！王假之，何谓也？曰：假，大也。夫所谓丰者，岂直土地之广，人民之众也哉？谓夫兵寝刑措，礼制乐作，上恬下熙，家给人足，蕃衍盛大，乃为丰也。原其所以致此者，孰使然哉？王实大之也。故子曰：「王假之，尚大也。」治天下者，审所尚而已。所尚者大，则其功博；所尚者小，则其效卑，必然之理也。贾谊曰：「天下者，器也。置之安处则安，置之危处则危。」魏征曰：「行帝道而帝，行王道而王，顾所行何如耳。」而昧者以为治乱在天，安危任数，遂废人事而不修，是不知天道也。说天者莫辩乎易，易之言如是，学者可以察矣。「勿忧，宜日中」，何谓也？曰：此圣人之所以处丰也。说者皆谓当斯之时，可以旡忧，愚谓不然。夫亨者，极盛之词也；勿者，禁止之辞也。书曰：「无疆惟休，亦无强惟恤。」又曰：「无疆惟休，亦大惟艰。」而况易之为书，告人以进退存亡、吉㓙得丧相为倚伏之理，惟恐不切至，故常言天地、日月、四时、鬼神以晓譬之，而岂以极盛之时，乃止之使勿忧乎？泰之九三曰：「旡平不陂，旡往不复，勿恤其孚，于食有福。」晋之六五曰：「悔亡，失得勿恤。」夬之九二曰：「惕号，莫夜有戎，勿恤。」家人之九五曰：「王假有家，勿恤，吉。」而丰之彖曰：「勿忧，宜日中。」此五象者，皆当文明极盛之时，愚人之所不忧，而圣人以为深忧，故其辞皆言「勿恤」者，深切之辞也。犹言天下盛极矣，能勿忧乎？故泰之「勿恤」，在平陂之间；晋之「勿恤」，在失得之际；夬之「勿恤」，在于「莫夜有戎」。家人之辞与丰相类，皆言王实大之，而可以勿忧乎？诗云：「母念尔祖，聿修厥德。」亦深切之词也，故曰「宜日中」。苏氏曰：「宜日之中，而不宜其既中也。夫有昼必有夜，有中必有昃，虽人不能易也，其能使之勿昃乎？易曰：日昃之离，不鼓缶而歌，则大耋之嗟。而此言宜日中者，何也？子曰：宜照天下也。盖丰之患，患在下情不得上达，上情不能下通，宜廓其照，如日之方中，不宜障蔽其明，如蔀屋之下也。昔者帝尧光宅天下，被于四表，至于海隅苍生，万邦黎献，共惟帝臣，嘉言罔伏，野无遗贤，不虐无告，不废困穷，斯日中之丰也，其有不亨者乎？」夫子既释其义，又从而畅之曰：「日中则昃，月盈则食，天地盈虚，与时消息，而况于人乎？况于鬼神乎？」由此言之，丰大之时，圣人之所畏也。说者乃谓无忧而可，岂不过甚矣哉！象曰：雷电皆至，丰，君子以折狱致刑。雷者，震也。电者，离也。雷电皆至，威明震耀之象也。君子以之「折狱致刑」者，明以折其情，威以致其罚也。而说者祖荀卿之论，以致刑为极刑，且言治世刑重，则失之远矣。舜典、皋陶惟明克允。故易凡言刑狱之事，未尝不取诸离。离也者，明也。明以动，折狱致刑之象也；明以止，无敢折狱之象也。动而明，明罚敕法之象也；止而明，明慎用刑之象也。明罚敕法，王者之事，故言先王。折狱致刑，有司之事，故言君子。君子者，通上下而言，故旅之「明慎用刑」，贲之「明庶政」，通称君子也。杂卦曰：「丰，多故也。」丰之为卦，以物之盛大而成，其在六爻，以世方多故为义。故，犹事也。当丰之时，天下可谓无事矣，而谓之多故，何哉？曰：天下惟有事也，然后知无事之为安。及其无事也，又将生事以为乐。虽然，亦其𫝑之不得不然也。书云：「位不期骄，禄不期侈。」今夫小民，方其脱于冻馁之中，苟可以糊其口，蔽其形，斯亦足矣，尚何事之有哉？及其有田以食，有庐以处，生生之资，稍稍充牣，则其口腹耳目之奉，婚姻伏腊之资，死丧宾客之度，岂能复视向者冻馁之时乎？此其所以多事也。天下国家亦犹是矣。富其蕃衍盛大之时，有不期丰而自丰者，顾所以自丰如何耳。丰其德，丰其典礼，丰其贤才，丰其法度，则本益固而末益茂。苟为不然，丰其宫室，丰其货利，丰其女子，丰其便嬖，则其所以自丰，乃所以自蔽也。是故丰有蕃盛之义，亦有蔽障之义焉。谓之多故，不亦宜乎？丰之诸爻，初九以六二为配主，九四以六五为夷主。九三、上六虽居正应之地，有「艮」「兑」之情，而不相遇焉。三「折其右肱」，上「阒其无人」者，盖有物以蔽之也。说者皆以初当配四，二当应五。若如所论，是阴与阴配，阳与阳配，旡自而相得矣。又曰：初、四同德相求，初为夷主，四为配主。两皆为主，则莫适为配矣。又曰：初遇四为配主，遇五为夷主。以一遇二，四为阳而五为阴，其于初九不能相当，益为缪戾难合矣。夫应在远，不可以言遇。遇者，适相值也。「姤」之卦，其训为「遇」。故初六在下，系于九二，而他爻争之则㓙。今初与二，四与五，皆以近相值而合，夫是以称「遇」也。或曰：睽诸文皆言「遇」，皆其应也，此独非应，何耶？曰：「睽」以乘离为义，六爻分散而不得相值，适其配而合焉，故可以言「遇」。「丰」以障蔽为义，九三、上六犹不相遇，而况初、四皆阳，二五皆阴，何自而遇哉？或曰：初与二遇，安得为配？而四与五遇，又曷为夷？二五皆阴，何以为主？曰：初以纯刚而遇二纯柔，安得不为配？四不纯刚而五不纯阴，安得不为夷？二五虽柔，而居中得位，安得不为主？「夷」，平也。初九之与六二，强弱异势，得为平乎？此「丰」之所以为多故也。初九：遇其配主，虽旬旡咎，往有尚。象曰：「虽旬旡咎」，过旬灾也。初九，「离」也。以阳居刚而在下卦之下，上旡其应，而承六二之「巽」，故曰「遇其配主」。初九之于六二，一阴一阳，是其配主矣，故曰「虽旬旡咎」。十日谓之「旬」，「旬」犹满也。九者数之极而加以初一，故有「十」之象焉。夫所恶于满者，为其溢也；所畏于盈者，为其亏也。日之中，月之望，皆有满盈之象，故「归妹」六五以「月几望」为「吉」，而「丰」之彖曰「宜日中」者，谨其所以持之而已矣。今以九居初而当「丰」之时，可谓满矣。为其遇于六二，有刚柔相济之象，是以虽满而「旡咎」也，故曰「往有尚」。「尚」，犹配也。既曰「遇其配主」，而又曰「往有尚」者，为其志在于自丰，有时而不往也。故子曰：「虽旬旡咎，过旬灾也。」孝经曰：「满而不溢。」其斯之谓欤！六二：丰其蔀，日中见斗，往得疑疾，有孚发若，吉。象曰：「有孚发若」，信以发志也。六二，「巽」也，以阴居柔而在下卦之中，上旡其应，而介于初九、九三之间，二爻皆「离」，而三又「兑」也，故曰「丰其蔀，日中见斗」。「蔀」，覆也，所以蔽日者也。三居下卦之上，自二视之，皆有「蔀」之象焉，而又以阳居刚，是以谓之「丰其蔀」也。二居中而上下皆「离」，故有「日中」之象。二体「巽」，「巽」为入，故有入于蔀覆之象。日之方中，旡所不照，而「丰其蔀」以自覆，则所见者斗而已。「斗」，星斗也。日中无见斗之理，所以云尔者，居蔀覆之下，盖有孔罅容光者焉，则曰「见斗而不见日」，固其宜矣。斗有七星，全卦中之体九画，六二为日中，其余七画，「斗」之象也。阴四画为「斗」，阳三画为「杓」。日隐而斗见，「日中见斗」之象也。日中为「斗」，何谓也？曰：人之聪明足以照知四远，而为物所蔽，则听于谗謟近习，而以察为明，虽在日中，见斗而不见日矣。见斗而不见日，然且自以为明，则受欺于奸谀而不悟也。故曰：「往得疑疾，有孚发若，吉」。巽为进退，为不果，故有「疑疾」之象。三体离「兑」，二女既同居矣，「巽」又往焉，能旡疑乎？故易曰：「一人行，三则疑也」。二往于三而得疑疾，然后以初九之离，发其丰蔀之蔽，是以系之吉也。孟子曰：「人恒过，然后能改。困于心，衡于虑，而后作。征于色，发于声，而后喻。入则无法家拂士，出则无敌国外患者，国恒亡。然后知生于忧患而死于安乐也。」或曰：初与三皆「离」也，以阳居刚，二爻之所同也。三为「蔀」而初为「发」，何哉？曰：三之「离」，有「兑」之象焉。「兑」者，日之昃也，而又居过中之位，则其所以为明者，乃其所以自蔽也。谓之「丰蔀」，不亦宜乎？所以然者，当「丰」之时，盛满为累，初、二为配，相与以成矣。又蔽于三而遇焉，则政失其中，上下壅塞，将穷其大而失其所居矣。此圣人之畏也。故子曰：「有孚发若，信以发志也。」其初九之谓乎？九三：丰其沛，日中见沫，折其右肱，旡咎。象曰：「丰其沛」，不可大事也；「折其右肱」，终不可用也。九三上体为「兑」，下体为「离」，以阳之上应乎上六之「艮」，而乘乎六二之「巽」，上承九四。四，震兑也，故曰「丰其沛，日中见沬」。古本作「丰其旆」，幡幔之属也。四体「震」，震为动而不纯乎刚，故有幡幔之象。以九居三，过乎刚矣。而益之以九四，是「丰其沛」也。三虽有上六之应，而四为之蔽，如幡幔之蔽明矣。以蔀为未足，又加沛以自障，则日中所见者，沫而已。「沫」，微星也。或曰：斗后小星也。「见沬」云者，言其容光之益小也。既「丰其蔀」，又「丰其沛」，非徒不见日，且不见斗矣。六二为日中，其余画七，犹有斗象。九三为「日中」，其余不止于七，则小星无名数之象也。或曰：九三何以为日中？曰：三有「离」象，「离」，南方也，日之中天也。故曰：「折其右肱，旡咎。」九三应在上六，上体「艮」，「艮」为手，居卦之上，有「右肱」之象焉。三体「兑」，「兑」为毁折，故有「折肱」之象焉。人之所恃以为用者，手足耳目而已。今也「丰其沛」，自蔽其明也；「折其右肱」，自蔽其动也。又谁咎乎？故子曰：「丰其沛，不可大事也。」言不足与有明也。「折其右肱，终不可用也」，言不足与有为也。或曰：既已自蔽其明矣，而犹可小事，何哉？曰：当丰之时，法行令具，上恬下熙，以之小事，孰能违者？特其君不明，则不可大有为耳。洪范所谓「作内吉，作外㓙」，亦其意也。然积日累月，将有三岁不觌之凶矣。九四：丰其蔀，日中见斗，遇其夷主，吉。象曰：「丰其蔀」，位不当也。「日中见斗」，幽不明也。「遇其夷主」，吉行也。九四上体为「震」，下体为「兑」，以阳居柔而在上卦之下，下旡其应，而承于六五之「巽」，故曰「丰其蔀，日中见斗」。六五之于九四，可谓「发其蔀」矣，而乃曰「丰其蔀」，何哉？曰：非九四之以六五为「蔀」也，乃六五之以上六为「蔀」也。六五之以上六为「蔀」，何也？曰：「蔀」，覆也，且言周密也。九三、上六居一卦之上，而以阳居刚，以阴居柔，有掩覆周密之象，是以同称「蔀」也。六五为日中，而「丰其蔀」以自蔽，则所见者斗而已，犹六二「见斗」之象也。六五何谓「日中」？曰：「丰」之二五，即「离」之二五，有日中之象焉。所以变「离」为「丰」者，上九一爻之易也。则上之为「蔀」，不亦宜乎？然而不言于五而言于四者，此则圣人互文见义，因九四有夷主之遇，而遂当六五之辞，不使学者易而知之耳。如使六二、六五两著其文，则学者怠而不思，而得非微显阐幽之自也。故子曰：「丰其蔀，位不当也。日中见斗，幽不明也。」谓上六居一卦之极，不当其位，而六五受其掩蔽，有幽不明之象焉。苟非「巽」乎九四之刚，何以获庆誉之吉矣？故曰：「遇其夷主，吉。」九四之于六五，有夷主之象焉。「夷」，平也。所谓君臣同德，上下相需者也。晏子曰：「君所谓可而有否焉，臣献其否以成其可；君所谓否而有可焉，臣献其可以替其否。」六五，君也，九四，臣也。五以阴居刚，而四以阳居柔。五体巽巽以下逮，四体震震以上行。此无太过，彼旡不及，谓之夷主，不亦宜乎？是以系之吉也。或曰：九四之震，有兑象焉，其能与五为夷，何也？曰：兑上无其与，下无其应，是震之辅也。有震无「兑」，则九四之刚或几乎过矣。震，动也；「兑」，说也。此四之所以为平也。故子曰：「遇其夷主，吉，行也。」行也者，其动象乎！六五：来章，有庆誉，吉。象曰：六五之「吉」，有庆也。六五，「巽」也。以阴居刚而在上卦之中，下旡其应而乘九四。四，「震兑」也，故曰「来章」。一阴一阳，合而成章。六五之于九四，所谓「来章」也。六二上有九三，故「往得疑疾」，然后「有孚」于初六。五上旡其应，故直言其来也。以「巽」从「震」，有不约而来者矣，故曰「有庆誉，吉」。阴之获阳，谓之「有庆」。「有庆」而又「有誉」者，为其能「巽」以下贤故也。欢欣交通，声名洋溢，其斯之谓欤？故子曰：「六五之吉，有庆也。」上六：丰其屋，蔀其家，𬮭其户，阒其无人，三岁不觌㓙。象曰：「丰其屋」，天际翔也。「𬮭其户，阒其无人」，自藏也。上六，「艮」也，以阴居柔，而在上卦之上，应九三之「兑」，而乘六五之「巽」，故曰「丰其屋，蔀其家」。上六以阴居柔，体是「艮」止，出阴之所，暗昧之时也。有应在三，隔于六五而不相遇焉，有物以蔽之也。处于至高，而重阴以自固，「丰其屋」之象也。既以重阴，而又以阴自蔽，「蔀其家」之象也。屋之为覆，高大周密，非直蔀与旆也。以屋为未足，又施蔀于其家。家，屋中也，其自为障蔽又甚矣。沫之微明且不得见，而况于斗与日乎？故曰「𬮭其户，阒其无人」。「𬮭其户」，其户闲也。「阒其无人」，其人亡也。艮为止，为门阙，有闭户之象焉。巽为入，为伏，故有「无人」之象焉。堂下远于百里，君门远于万里。「辟四门，明四目」，犹惧壅塞，而况闭之乎！贵而旡位，高而旡民，贤人在下位而旡辅，所与居者，谗謟近习而已，所谓「阒其无人」者也。屋高而蔀盛，户闭而室窒，人亡而鬼瞰，欲无㓙，得乎？故曰「三岁不觌㓙」。夫祸患之来，非一日之故也。壅蔽之患，生于暗昧；委靡之势，成于宴安。逮夫邪佞满前，忠良废斥，纲纪败坏，风俗陵夷，人心携离，主势孤立，如此者，岂一日之故哉？其所由来者渐矣。偷安朝夕，幸或可以无他，旷日持久，未尝不至于大乱。扬子曰：「三年不日，日视必盲；三年不目，目晴必蒙。」今也深藏而远匿，失人而绝物，至于三岁之久而旡所见焉，㓙斯至矣，秦二世是也。外倚长城之强，内增阿房之固，自以为帝王万世之业，可谓丰其屋而蔀其家矣；忠谏者族，偶语者弃市；诛大臣，灭宗室，深居高拱，使群臣但闻其声，不得见其面，可谓𬮭其户，寂其无人矣；山东之盗，指为妖言；宫中之鹿，指而为马；天下之士，相率以逃秦难，而赵高之徒日侍左右，伺其隙而图之，可谓人亡而鬼瞰其室矣。三岁不觌，㓙其宜乎？子曰：丰其屋，天际翔也；𬮭其户，阒其无人，自藏也。屋翔于天际，而自藏于蔀中，其可谓之不祥矣。序卦曰：「丰者，大也。穷大者必失其居，故受之以旅。」旅，丰之反也。自丰之旅，离反居上，震反为艮，上下相易而成也。离，丽也；「震」，动也；「艮」，止也。动而丽乎内，所以为丰也；止而丽乎外，所以为旅也。若夫家人之象，亦取其人而丽乎内矣。夫物禁太甚，其极必反。「丰」之上六，其大穷也，是以大其丰屋蔀家而为旅也。秦二世末年，为赵高所绐，出居望夷之官，岂非穷大者失其所居之验乎？旅：小亨，旅贞吉。彖曰：「旅，小亨」，柔得中乎外而顺乎刚，止而丽乎明，是以「小亨，旅贞吉」也。旅之时义大矣哉！下艮上离，成卦曰旅者，初为艮，二为巽，三为兑，四为离。艮，止也；离，明也。止而丽乎明，斯谓之旅，可乎？曰：未也，为其有巽、兑之象焉。巽，入也；兑，说也。入而说之，则寓人之情可见矣，是以谓之旅也。艮，东北也；离，南方也。自东北而之乎南，非其类，又非其配也，谓之旅可乎？曰：未也，为其有巽、兑之象焉。巽，东南也；兑，西方也。方以类聚，而艮独寓焉，是以谓之旅也。「旅小亨，旅贞吉」，何谓也？曰：小亨者，卑小而后亨也；贞吉者，贞固而后吉也。夫旅者，违其国，去其家，而托于他人者也。苟亢傲自尊，与物屏绝，则穷困而莫之救矣；轻躁妄行，先时而动，则颠沛而无所归矣。惟能卑小而下人，然后可以冀其亨；惟能贞固而待时，然后可以保其吉。是以旅之二五，其画皆柔，其体皆巽，柔巽以行之，是以系之「小亨」也。下卦为艮，上卦为离，止而丽乎明，是以系之「贞吉」也。故子曰：「旅小亨，柔得中乎外而顺乎刚，止而丽乎明，是以小亨，旅贞吉也。」上文「小亨」二字疑是衍文。旅之二五，皆柔得中，而但言得中乎外者，六二之义未可以亨，至五而后亨也。得中乎外，然后为旅。若得中乎内，旅之云乎？曰：然则二之得中，何谓也？曰：此所谓「贞吉」者也。以柔居刚，上有所托，下有所辅，是以能亨。以柔居柔，上无所托，而下无所与，其能亨乎？贞固守之，斯为吉也。故曰：「旅之时义大矣哉！」夏少康、周宣王、齐威、晋文、卫文、赵武，应其时义矣。说者或曰：「旅卦为孔、孟历聘周游之义。」非也。孔、孟东西南北之人也，视旅犹家也，岂所谓穷大而失其所居者乎？岂所谓「柔得中而顺乎刚，止而丽乎明」者乎？斯不待辩而明矣。象曰：山上有火，旅，君子以明慎用刑，而不留狱。山者，「艮」也；火者，「离」也。山上有火，非火之所归，是以谓之「旅」也。君子以之明谨用刑而不留狱者，明取诸「离」也，慎取诸「艮」。火行则山无余蓄，刑用则狱无留情，是以君子有取于斯也。杂卦曰：「亲寡，旅也。」旅之为卦，以失其所居而成。其在六爻，以所亲众寡为义。何则？旅者，去国之流人也。所亲者寡，不亦宜乎？阳为刚，阴为柔。刚者，人之所托也；柔者，托于人者也。上为尊，下为卑。尊者，人之所托也；卑者，托于人者也。是故「旅」之诸爻，以阴托于阳、以下托于上者，得其所托者也；以刚托于柔、以上托于下者，失其所托者也。初六有「志穷」之灾，六二有「即坎」之贞，九三有「焚次」之厉，九四有「于处」之安，六五有「射雉」之誉，上九有「焚巢」之㓙者，各以其所亲众寡而辩之矣。初六：旅琐琐，斯其所取灾。象曰：「旅琐琐」，志穷灾也。初六，「艮」也。以阴居刚，而在下卦之下，承六二之「巽」，而应乎九四。四，离兑也，故曰「旅琐琐」。「琐琐」，小之志也。「旅」之初六，即「丰」之上六。「丰」，大也。穷于大，必反于小，故「旅」之初六，至于「琐琐」也。六二阴柔，既不足以为托，而于初六亦无相比之情，四虽其应，而旅于他邦，不能以相援，处于最下，体乎艮止，卑辱已甚，而旡改辙之图，二体巽巽，为近利市三倍，初六承之，其志已细，是以谓之「琐琐」也。君子见其在旅之「琐琐」，而知其所以取灾，故曰「斯其所取灾」。方其在丰也，甘于暗昧，溺于宴安，养尊处高，自绝于物；及其在旅也，不顺乎刚，不丽乎明，而徒苟朝夕之安，争寻常之利，此其所以「取灾」也。故子曰：「旅琐琐，志穷灾也。」不能保其宗庙社稷而旅于他邦，必琐而又琐，志穷而止此矣。黎侯寓于卫，卫不能图而黎侯安之，式微之诗所以有「琐兮尾兮」之刺也。六二：旅即次，怀其资，得童仆贞。象曰：「得童仆贞」，终无尤也。六二，「巽」也。以阴居柔而在下卦之中，上无其应，而乘初六之「艮」，上承九三。三，震兑也，故曰「旅即次」。「次」，舍也。巽为入，而二又居中，故有「即次」之象。六二之于九三，得其所托矣。二，「巽」也；三，「震」也。以「巽」从震，是以系之「即次」也。序曰：「旅而无所容，故受之以巽。」巽者，旅之所容之道乎？故曰：「怀其资，得童仆贞。」「巽」为近利，而二又居中，故有怀「资」之象。「艮」为少男，而在二之下，故有「得童仆」之象。「即次」而怀其资，待时之义也。时则未至，未可以亨，而有次可以安，有资可以给，有童仆可以赖，贞固守之，斯为得矣。故子曰：「得童仆贞，终无尤也。」不言吉者，旅于他人无咎，幸矣，何吉之云乎？彖之所谓「吉」者，要其终而言之也。晋文公在狄十有九年，得民之心，得士之力，有赵衰、狐偃以为腹心，有魏犨、贾佗以为股肱。越王句践栖于会稽二十余年，亲其人民，厚其货财，有大夫种以治其外，有范蠡以治其内，可谓「即次」而怀资，「得童仆贞」者矣。卫侯衎之出也，厚成叔吊于卫，归语臧孙曰：「卫君其必归乎？有太叔仪以守，有母弟𫚋以出，或抚其外，或营其内，能无归乎？」及臧孙唁于郊，见子展、子鲜，亦曰：「卫君必入矣。」二子者，或挽之，或推之，欲无入，得乎？此其得童仆，是以终无尤也。九三：旅焚其次，丧其童仆，贞厉。象曰：「旅焚其次」，亦以伤矣。以旅与下，其义丧也。九三上体为兑，下体为震，以阳居刚而在下卦之上，上无其应，而承九四之离，乘六二之巽，故曰：「旅焚其次，丧其童仆。」三之所托者，四也。三于四为强矣，而反托之两刚，不能以相事。四又体离，离为火，故有焚次之象焉。三之所乘者，二也。二礼巽，三礼震，以巽承震，故亦有童仆之象焉。然巽为进退、为不果，震为决躁，兑为毁折，故有「丧其童仆」之象焉。在旅无亲，所亲者童仆，惟以身处柔让，而从者强力，然后可以脱于危难之中。今九三以阳居刚，而六三以阳居柔，是身为强暴，而童仆𡯁羸，又有毁折之象焉，是以知其童仆之丧矣。次舍既焚，童仆又丧，而犹贞固守之，危之道也。故曰「贞厉」。子曰：旅焚其次，亦以伤矣。以旅与下，其义丧也。身为旅人，亢傲自尊，轻躁妄动，不能亲上而务与下交，宜其丧也。鲁昭公孙于齐，齐侯取郓以居之。昭公据郓以与鲁战，既而郓人溃叛，齐、晋卑之，有子家羁而忽其谋，有叔孙婼而致其死。春秋三十二年书「公在乾侯」，言内外不能用其人也。其九三之谓乎？或曰：子以艮为童仆，六二非艮也，而有童仆之象，何哉？曰：此相因而成象也。「坤」之「龙战」，「大壮」之「丧羊」，亦犹是矣。九四：旅于处，得其资斧，我心不快。象曰：「旅于处」，未得位也；「得其资斧」，心未快也。九四上体为「离」，下体为「兑」，以阳居柔而在上卦之下，应初六之「艮」，而承六五之「巽」，下乘九三。三，震兑也，故曰：「旅于处，得其资斧。」四已进乎上卦，而未得其中，托于六五，虽刚柔无以相尚，而有相与之情，是亦得其所托矣，故有「于处」之象焉。「资」，当作「齐」。说文曰：「子夏传及众家皆作齐斧。」应劭云：「齐，利也。」汉书：「王莽遣王寻屯洛阳，将发，亡其黄钺。」其士房杨曰：「此经所谓丧其齐斧者也。」四「离」体「兑」，「兑」为金，「离」为戈兵，又以阳居刚，故有「齐斧」之象焉。夫「旅」者，失其所居者也。而四有「于处」之辞，是将复其国者也。「得其资斧」，是执其威柄者也。然其位不中，其应在下，有「艮兑」之情，而不得相遇焉，故曰「我心不快」。得其处而未得其位，「得其资斧」而未得其用，其心安得而快乎？所以然者，在旅之时，惟「巽」为可以贞，惟「巽」为可以「亨」。今九四离乎「离兑」，是以未逞其志也。故子曰：「旅于处，未得位也。得其资斧，心未快也。」郑厉公之在栎，卫庄公之在戚，所谓「旅于处而未得位」者与？然二君者，不足以充九四之义，四盖六五之未得志者也。说者谓于处不若即次之安。按春秋书昭公次于阳州，次于乾侯。阳州，齐地也。乾侯，晋地也。书「公至自齐，居于郓」。左氏曰：「公至自齐，处于郓，言鲁地也。」由是言之，「次」者寓于他人，而处者入其故国也。二远于五，而四已近之，此其所以不同兴。六五：射雉，一矢亡，终以誉命。象曰：「终以誉命」，上逮也。六五，「巽」也，以阴居刚，而在上卦之中，下旡其应，而介于九四、上九之间，二爻皆「离」，而四又「兑」也，故曰「射雉，一矢亡」。「离」为文明，为飞鸟，为弧矢，故有「射雉」之象。四之「离」，有「兑」象焉。「兑」为毁折，故有「一矢亡」之象。「一矢亡」者，先钝而后利之义也。夫射雉者，岂以一矢之丧而遂去之哉？五，君位而六居之，其体巽巽为入。上有所托，下有所辅，而又有获文明之象焉。此失国之君，藉内外之𫝑，诛其雠，入其国，而复其位者也，能无一矢之亡乎？唐宪宗曰：「胜负兵家之常，岂得因渠一败，便沮成计乎？」故爻辞不复称「旅」，而曰「终以誉命」。彖之所谓「柔得中乎外而顺乎刚，是以小亨」者也。说者或谓射以一矢而亡其雉，不惟文意不顺，而六五居二「离」之间，射用一矢，于象疏矣。故子曰：「终以誉命，上逮也。」命，爵命也。「以誉命」者，得誉于下，而受命于上也。为天子者命于天，为诸侯者命于天子，为大夫者命于诸侯，皆射矢获之象也。谓其承于上九，是以自天命之矣。或曰：「离为弧矢，则四、上二爻当之矣，而六五为射雉之象，何哉？」曰：九四者，六五之未得志者也。六五、上九者，九四之成功者也。故一矢之亡，不足以损其大计也。四蓄其资，五收其用，「离」为丽，「巽」为入，系之于五，不亦可乎？或曰：「上焚其巢，则五将安所托乎？」曰：五之有上，五之托也。上焚其巢，已极之灾也。楚灵、齐湣，方其盛也，岂不足以为托乎？上九：鸟焚其巢，旅人先笑后号啕，丧牛于易，㓙象曰：以旅在上，其义焚也。「丧牛于易」，终莫之闻也。上九，离也。以阳居柔，而在上卦之上，下无其应，而乘六五之「巽」，故曰「鸟焚其巢」。离为火，为飞鸟，为科上稿巽，为风，故有「鸟焚其巢」之象。在旅时，以刚居上，炎炎之极，则有自焚之祸灾，故曰「旅人先笑后号啕」。「旅人」，谓九三也。三与上应，三为旅而上为巢也。二爻皆以刚居上，旡相与之情，故三焚其次，上焚其巢。「三焚其次」者，承于九四之离，为他人之所焚也。「上焚其巢」者，自焚也。三体兑震，「兑」为说，震为大声，故有「先笑后号啕」之象。夫旅者，本失其巢矣，初幸其焚，故笑；后无所归，故「号啕」也。或曰：下卦，内也；上卦，外也。今六二、九三为次，而六五、上九为巢，何也？曰：为其在旅，故内其次而外其巢矣。妇人内夫家而外父母家，亦犹是也。故曰丧牛于易㓙。易，疆埸也。九居一卦之外，有疆埸之象焉。牛，顺物也。「坤」之三女，皆有牛象，犹震、坎、艮之称马也。上九乘于六五，五体「巽」，故有牛之象焉。「离」有蓄牝牛之吉，而上九之离至于「丧」者，为其以刚在上，穷其力而至于奔也。书曰：「马牛其风。」是以九三之焚其次，则巢犹在也；丧其童仆，则牛尚存也。巢在则有可归之理，牛存则有可行之资。今也巢焚而牛丧，欲归则无其所，欲行则无其资，㓙斯至矣。故子曰：以旅在上，其义焚也。九三、上九，其为在上，而与下则同，盖互相发耳。丧牛于易，终莫之闻也。疆埸远于城邑，人所不闻，以喻上九失人而绝物，故自焚自丧而莫之救也。魏公子无忌客于赵，秦日夜出兵攻魏，魏急而公子不救。毛公薛公谓曰：「公子之所以重于赵者，以有魏也。使秦破魏而夷先王之宗庙，公子当何面目立于天下乎？」此焚巢之喻也。齐崔氏之亡也，杼以难告，庆封帅甲以攻崔氏，杀其妻子而俘其家，复命于崔子，且御而归之。至则无归矣，乃缢。此先笑后号啕之喻也。周易经传集解卷二十八，",-1)])])}const _=t(r,[["render",c]]);export{m as __pageData,_ as default};
